`,ky=`// northern-pass - G mixolydian, 96 bpm. mood: adventurous, epic.
// Setting out over snowy mountains: a horn call, a striding bass, a frame drum
// and a tin whistle. Level 1 adds the lute, level 2 the full march.
// Ten sections of eight cycles (3m20s before it repeats): four chord journeys,
// and the horn call climbs, turns and answers itself section by section.
setcpm(96 / 4)

let A = "<G F C G G F Dm F>"
let B = "<C G F C Em F G Dm>"
let C = "<Am F C G Am Em F G>"
let D = "<Dm C F G Dm Am F G>"
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, D], [8, B], [8, A], [8, C], [8, D], [8, A])

// the horn call: eight cycles, a rest of a bar after each call
let call = "<[0@3 4@2 ~ 2 ~] ~ [2@3 1@2 ~ 0@2] ~ [4@3 5@2 ~ 7 ~] ~ [5@3 4@2 ~ 2 ~] [2@2 1@2 0@4]>"
let horn = arrange([8, call], [8, call.add(2)], [8, call.rev()], [8, call.add(-2)], [8, call.add(4)],
  [8, call.rev().add(2)], [8, call], [8, call.add(-2).rev()], [8, call.add(2)], [8, call.rev().add(-2)])

stack(
  // 0: open fifths in the strings, the striding bass, the horn call
  chord(P).voicing().mode("below:d4")
    .s("supersaw").unison(2).detune(.2).attack(.6).clip(.9).release(.2).gain(.17)
    .lpf(1500).room(.6).roomsize(6).orbit(2),
  note(P.rootNotes(2)).s("triangle").attack(.02).decay(.25).sustain(.4).release(.2).gain(.5)
    .struct("x ~ x ~ x x x x"),
  n(horn).scale("g3:mixolydian")
    .s("sawtooth").attack(.08).release(.3).gain(.4)
    .lpf(500).lpenv(3).lpa(.12).lpd(.6).room(.7).roomsize(6).orbit(2),
  s("frame:1 ~ ~ ~ frame:1 ~ ~ ~").gain(.45).room(.3),
  // 1: the lute joins, the whistle answers the horn
  layer(1, stack(
    n("~ 0 ~ 2 ~ 0 ~ 2").chord(P).voicing().mode("above:g3")
      .s("strum").gain(.55).room(.4),
    n("~ ~ ~ ~ 4 [5 4] 2 ~ ~ ~ ~ ~ 2 [3 2] 0 ~".slow(2).add("<0 0 -1 0 -2 0 -3 0>"))
      .scale("g4:mixolydian")
      .s("whistle").gain(.45).attack(.03).release(.15).lpf(2800).room(.5).roomsize(6).orbit(2))),
  // 2: the march
  layer(2, stack(
    s("timp:0 ~ ~ timp:0 ~ ~ timp:0 ~").gain(.55).room(.3),
    s("~ ~ frame:0 ~ ~ ~ frame:0 ~").gain(.4),
    n("<0 0 0 0 0 0 0 0>*2".add("<0 0 -1 0 0 0 -2 0>")).scale("g3:mixolydian")
      .s("sawtooth").attack(.05).release(.15).gain(.18).lpf(1000).lpenv(2).lpd(.3).roomsize(6).orbit(2)))
).postgain(.45)
`,Ay=`// vibe-wars - E aeolian, 100 bpm. mood: adventurous, epic.
// The title theme. Horns rise a fifth and an octave in the first bar, so the
// flash lands on a statement; the B7 turns it back to the top without a seam.
// One level: the splash plays no intensity ramp, so level 0 is the whole theme.
// Four sections of twenty cycles (3m12s) carry the theme up and down the scale.
setcpm(100 / 4)

let P = "<Em C^7 Am7 B7>"
let theme = "<[0@2 4@2 7@4] [7@2 6@2 5@2 4@2] [3@2 5@2 4 3 2 1] [1@2 2 3@2 4@3]>"

let tune = arrange([20, theme], [20, theme.add(2)], [20, theme.add(4)], [20, theme.add(-2)])

stack(
  chord(P).voicing().mode("below:g4")
    .s("sawtooth").lpq(4).attack(.4).clip(.9).release(.2).gain(.2)
    .lpf(1800).room(.8).roomsize(6).orbit(2),
  chord(P).voicing().mode("below:e4")
    .s("supersaw").unison(1).attack(.4).clip(.9).release(.2).gain(.2).lpf(1500).room(.6).roomsize(6).orbit(2),
  note(P.rootNotes(2)).s("triangle").attack(.04).clip(.9).release(.2).gain(.5),
  n(tune).scale("e3:minor")
    .s("sawtooth").attack(.06).release(.3).gain(.5)
    .lpf(500).lpenv(3).lpa(.08).lpd(.5).room(.6).roomsize(6).orbit(2),
  s("timp:2 ~ timp:2 ~ timp:2 ~ timp:2 timp:2").gain(.4).room(.3),
  s("taiko:1 ~ ~ ~ taiko:1 ~ ~ ~").gain(.35),
  s("crash:0 ~ ~ ~ ~ ~ ~ ~").slow(4).gain(.3),
  n("0 2 4 2 0 2 4 7").chord(P).voicing().mode("above:e3").s("harp").gain(.35).room(.6).roomsize(6).orbit(2)
).postgain(.335)
`,jy=`// victors-hymn - Bb major, 108 bpm. mood: triumphant, epic.
// Banners up. A brass chorale over choir and bells: noble, not cheesy. Level 0
// is the hymn, level 1 adds the timpani roll and the cymbal.
// Eleven sections of eight cycles (3m16s before it repeats): four chord
// journeys, and the brass sings a new verse of the hymn over each.
setcpm(108 / 4)

let A = "<Bb F Gm7 Eb^7 Bb F Eb F>"
let B = "<Gm7 Eb^7 Bb F Cm7 Gm7 F Bb>"
let C = "<Eb^7 Bb F Gm7 Eb^7 Cm7 F Bb>"
let D = "<Bb Dm7 Eb^7 F Gm7 Cm7 F Bb>"
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, D], [8, B], [8, C], [8, A], [8, D], [8, B], [8, A])

// the hymn: eight cycles
let hymn = "<[2@2 4 3@2 2 1] [0@2 1 2@4] [4@2 5 4@2 2 1] [0@6 ~ ~] [4@2 5 6@2 4 3 2] [7@3 6 5 4 ~ 2] [5@2 4 2@2 3 4 5] [0@6 ~ ~]>"
let tune = arrange([8, hymn], [8, hymn.add(2)], [8, hymn.rev()], [8, hymn.add(-2)], [8, hymn.add(3)],
  [8, hymn.rev().add(2)], [8, hymn.add(-2).rev()], [8, hymn], [8, hymn.add(4)], [8, hymn.rev()], [8, hymn])

stack(
  // 0: choir and strings hold the chord, the brass sings the tune
  chord(P).voicing().mode("below:f4")
    .s("sawtooth").lpq(4).attack(.5).clip(.9).release(.2).gain(.2)
    .lpf(2200).room(.85).roomsize(6).orbit(2),
  chord(P).voicing().mode("below:d4")
    .s("supersaw").unison(1).attack(.5).clip(.9).release(.2).gain(.22).lpf(1600).room(.6).roomsize(6).orbit(2),
  note(P.rootNotes(2)).s("triangle").attack(.04).clip(.9).release(.2).gain(.5),
  n(tune).scale("bb3:major")
    .s("sawtooth").attack(.1).release(.3).gain(.5)
    .lpf(500).lpenv(3).lpa(.1).lpd(.6).room(.7).roomsize(6).orbit(2),
  s("bells:1 ~ ~ ~ ~ ~ ~ ~").slow(2).gain(.3).room(.9).roomsize(6).orbit(2),
  // 1: banners snap in the wind
  layer(1, stack(
    s("timp:2*8").gain(.35).room(.3),
    s("crash:0 ~ ~ ~ ~ ~ ~ ~").slow(4).gain(.3),
    n("0 2 4 2 0 2 4 7").chord(P).voicing().mode("above:bb3").s("harp").gain(.4).room(.6).roomsize(6).orbit(2)))
).postgain(.335)
